<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();$context=require_admin('products.review');$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET'){$stmt=$db->query('SELECT c.*,p.name AS parent_name,(SELECT COUNT(*) FROM products pr WHERE pr.category_id=c.id OR pr.subcategory_id=c.id) product_count FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(c.parent_id,c.id),c.name');json_response(200,['success'=>true,'categories'=>$stmt->fetchAll()]);}if(in_array($method,['POST','PATCH'],true)){$body=get_json_body();$name=trim((string)($body['name']??''));$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',strtolower((string)($body['slug']??$name))),'-'));if(mb_strlen($name)<2||mb_strlen($name)>120||$slug==='')json_response(422,['success'=>false,'message'=>'Category name is invalid.']);$status=in_array($body['status']??'active',['active','inactive'],true)?$body['status']:'active';if($method==='POST'){$db->prepare('INSERT INTO categories (parent_id,name,slug,status,created_at,updated_at) VALUES (:parent,:name,:slug,:status,UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['parent'=>$body['parent_id']??null,'name'=>$name,'slug'=>$slug,'status'=>$status]);json_response(201,['success'=>true,'message'=>'Category created.','category_id'=>(int)$db->lastInsertId()]);}$id=(int)($body['id']??0);$db->prepare('UPDATE categories SET parent_id=:parent,name=:name,slug=:slug,status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['parent'=>$body['parent_id']??null,'name'=>$name,'slug'=>$slug,'status'=>$status,'id'=>$id]);json_response(200,['success'=>true,'message'=>'Category updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
